export function promptPackMarkdown(items: PackItem[], tenant: string): string {
  const lines = [`# ${PROMPTS.title}: ${tenant}`, '', PROMPTS.intro, '']
  for (const it of items) lines.push(`## ${it.title}`, '', '```', it.prompt, '```', '')
  return lines.join('\n')
}

